export const WORLD_ANIMALS_BY_ID: Record<string, WorldAnimal> = Object.fromEntries(
  WORLD_ANIMALS.map((a) => [a.id, a])
);

export const ANIMAL_CATEGORIES: AnimalCategory[] = [
  'Mammals & Safari',
  'Marine & Aquatic',
  'Birds & Avian',
  'Reptiles & Amphibians',
  'Polar & Arctic',
  'Insects & Invertebrates',
];

export function getAnimalsByCategory(category?: AnimalCategory | 'all'): WorldAnimal[] {
  if (!category || category === 'all') return WORLD_ANIMALS;
  return WORLD_ANIMALS.filter((a) => a.category === category);
}

export function getRandomAnimal(category?: AnimalCategory | 'all'): WorldAnimal {
  const list = getAnimalsByCategory(category);
  return list[Math.floor(Math.random() * list.length)]!;
}
